<?php
declare(strict_types=1); namespace Comfino\Common\Shop\Product; use Comfino\Common\Shop\Cart; class CategoryFilter{ private $categoryTree; public function __construct(CategoryTree $categoryTree){$this->categoryTree=$categoryTree;} public function isCategoryAvailable($categoryId,$excludedCategoryIds):bool{if(in_array($categoryId,$excludedCategoryIds,true)){return false;}if(($categoryNode=$this->categoryTree->getNodeById($categoryId))===null){return false;}foreach($excludedCategoryIds as $excludedCategoryId){if(($excludedCategory=$this->categoryTree->getNodeById($excludedCategoryId))===null){continue;}if($categoryNode->isDescendantOf($excludedCategory)){return false;}}return true;} public function isCartValid($cart,$excludedCategoryIds):bool{if(empty($excludedCategoryIds||empty($cart->getCartItems()))){return true;}$cartCategoryIds=$cart->getCartCategoryIds(); if(count(array_intersect($cartCategoryIds,$excludedCategoryIds))>0){return false;}foreach($cartCategoryIds as $categoryId){if(!$this->isCategoryAvailable($categoryId,$excludedCategoryIds)){return false;}}return true;}}